from typing import List

class Solution:
    def closestPrimes(self, left: int, right: int) -> List[int]:
        def is_prime(n):
            if n <= 1:
                return False
            if n <= 3:
                return True
            if n % 2 == 0 or n % 3 == 0:
                return False
            i = 5
            while i * i <= n:
                if n % i == 0 or n % (i + 2) == 0:
                    return False
                i += 6
            return True

        primes = []
        for num in range(left, right + 1):
            if is_prime(num):
                primes.append(num)

        if len(primes) < 2:
            return [-1, -1]

        min_diff = float('inf')
        closest_pair = [-1, -1]

        for i in range(len(primes) - 1):
            diff = primes[i + 1] - primes[i]
            if diff < min_diff:
                min_diff = diff
                closest_pair = [primes[i], primes[i + 1]]

        return closest_pair
```

This solution defines a helper function `is_prime` to check if a number is prime. It then iterates through the range from `left` to `right`, collecting all prime numbers in a list. If there are fewer than two prime numbers in this range, it returns `[-1, -1]`. Otherwise, it finds the pair of prime numbers with the smallest difference and returns it.

