from typing import List

class Solution:
    def leftRightDifference(self, nums: List[int]) -> List[int]:
        n = len(nums)
        leftSum = [0] * n
        for i in range(1, n):
            leftSum[i] = leftSum[i-1] + nums[i-1]

        total = sum(nums)
        answer = []
        for i in range(n):
            rightSum_i = total - nums[i] - leftSum[i]
            answer.append(abs(leftSum[i] - rightSum_i))

        return answer

