class Solution:
    def countMatchingSubarrays(self, nums: List[int], pattern: List[int]) -> int:
        def match(x: int, y: int, p: int) -> bool:
            if p == 1:
                return x < y
            elif p == 0:
                return x == y
            elif p == -1:
                return x > y

        count = 0
        n = len(nums)
        m = len(pattern)

