from typing import List
from collections import defaultdict

class Solution:
    def countPairsOfConnectableServers(self, edges: List[List[int]], signalSpeed: int) -> List[int]:
        # Build the graph
        graph = defaultdict(list)
        for a, b, weight in edges:
            graph[a].append((b, weight))
            graph[b].append((a, weight))

        def dfs(node, parent, distance):
            count = 0
            if distance % signalSpeed == 0:
                count += 1
            for neighbor, weight in graph[node]:
                if neighbor != parent:
                    count += dfs(neighbor, node, distance + weight)
            return count

        n = len(graph)
        result = [0] * n

        for c in range(n):
            groups = []
            for neighbor, weight in graph[c]:
                count = dfs(neighbor, c, weight)
                groups.append(count)

            # Calculate the number of connectable pairs for server c
            total_pairs = 0
            for i in range(len(groups)):
                for j in range(i + 1, len(groups)):
                    total_pairs += groups[i] * groups[j]
            result[c] = total_pairs

        return result
```

This solution constructs an adjacency list representation of the graph from the given edges. It then uses a depth-first search (DFS) to count the number of nodes reachable from each neighbor of the current server `c` such that the distance from `c` to these nodes is divisible by `signalSpeed`. The number of connectable pairs for each server `c` is calculated by considering all pairs of these counts.

