class Solution:
    def minimumSubstringsInPartition(self, s: str) -> int:
        def is_balanced(sub):
            from collections import Counter
            count = Counter(sub)
            freqs = set(count.values())
            return len(freqs) == 1

        n = len(s)
        dp = [float('inf')] * (n + 1)
        dp[0] = 0

        for i in range(1, n + 1):
